def min_points(intervals):
    if not intervals:
        return 0

    intervals = sorted(intervals, key=lambda interval: interval[1])

    points = 0
    current_point = None

    for start, end in intervals:
        if current_point is None or start > current_point:
            current_point = end
            points += 1

    return points
